examples.template:
MonarchApprovalTimeline(
    [
        MonarchApprovalTimelineStep(
            id: {{steps.0.id}},
            label: {{steps.0.label}},
            status: {{steps.0.status|case}},
            actor: MonarchApprovalPerson({{steps.0.actor.name}}),
            date: {{steps.0.at|date}}
        ),
        MonarchApprovalTimelineStep(
            id: {{steps.1.id}},
            label: {{steps.1.label}},
            status: {{steps.1.status|case}},
            actor: MonarchApprovalPerson({{steps.1.actor.name}}),
            date: {{steps.1.at|date}},
            comment: {{steps.1.comment}}
        ),
        MonarchApprovalTimelineStep(
            id: {{steps.2.id}},
            label: {{steps.2.label}},
            status: {{steps.2.status|case}},
            note: {{steps.2.note}}
        ),
        MonarchApprovalTimelineStep(
            id: {{steps.3.id}},
            label: {{steps.3.label}},
            status: {{steps.3.status|case}},
            approvers: [MonarchApprovalPerson({{steps.3.approvers.0.name}}), MonarchApprovalPerson({{steps.3.approvers.1.name}})]
        ),
        MonarchApprovalTimelineStep(id: {{steps.4.id}}, label: {{steps.4.label}}, status: {{steps.4.status|case}}),
    ],
    now: {{now|date}}
)
